def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    alive = []
    prev_bids = []
    opp_need_count = 0
    rich_opp = 0

    for opp_id in opponents_status:
        opp = opponents_status[opp_id]
        if opp.get('alive'):
            alive.append(opp)
            if opp.get('hp', 0) <= 3 or opp.get('no_water_days', 0) >= 1:
                opp_need_count += 1
            if opp.get('budget', 0) >= 120:
                rich_opp += 1
            prev = opp.get('previous_trace', {})
            if prev and prev.get('bid') is not None:
                prev_bids.append(prev.get('bid', 0))

    if budget <= 0:
        return 0

    if not alive:
        return min(budget, 18.0)

    highest_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = sum(prev_bids) / len(prev_bids) if prev_bids else 0.0

    scarcity = 0
    if supply <= 16:
        scarcity = 2
    elif supply <= 19:
        scarcity = 1

    urgency = 0
    if hp <= 2:
        urgency = 3
    elif hp <= 4:
        urgency = 2
    elif hp <= 6 or no_water_days >= 1:
        urgency = 1

    if urgency >= 3:
        bid = max(0.92 * DAILY_SALARY, highest_prev + 3.0)
        if scarcity >= 1:
            bid += 8.0
        return min(budget, bid)

    if urgency == 2:
        if highest_prev >= 150:
            bid = 52.0 + 6.0 * scarcity
        elif highest_prev >= 95:
            bid = highest_prev + 2.5 + 4.0 * scarcity
        else:
            bid = 58.0 + 6.0 * scarcity + 3.0 * opp_need_count
        return min(budget, bid)

    if urgency == 1:
        if highest_prev >= 160:
            bid = 34.0 + 4.0 * scarcity
        elif highest_prev >= 110:
            bid = 46.0 + 5.0 * scarcity
        else:
            bid = max(40.0, avg_prev * 0.62) + 4.0 * scarcity
        if rich_opp >= 2 and scarcity >= 1:
            bid += 4.0
        return min(budget, bid)

    if highest_prev >= 170:
        bid = 20.0 + 3.0 * scarcity
    elif highest_prev >= 130:
        bid = 28.0 + 4.0 * scarcity
    elif highest_prev >= 90:
        bid = min(highest_prev + 1.5, 52.0 + 5.0 * scarcity)
    else:
        bid = 32.0 + 4.0 * scarcity

    if day >= 8 and hp >= 7:
        bid *= 0.9

    if budget < 45:
        bid = min(bid, budget)
    else:
        bid = min(bid, budget, 0.78 * DAILY_SALARY + 10.0 * scarcity)

    if bid < 0:
        bid = 0
    return bid

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context['supply'])
    day = int(day_context['day'])

    # Identify alive opponents and read yesterday bids
    alive_opps = []
    yesterday_bids = []
    for opp_id, opp in opponents_status.items():
        if opp.get('alive', False):
            alive_opps.append(opp)
            prev = opp.get('previous_trace', {}) or {}
            b = prev.get('bid', None)
            if b is not None:
                try:
                    yesterday_bids.append(float(b))
                except Exception:
                    pass

    # If no info, play baseline conservative
    if not alive_opps or not yesterday_bids:
        base = DAILY_SALARY * 0.55
        return max(0.0, min(float(my_status['budget']), base))

    highest_prev_bid = max(yesterday_bids)
    avg_prev_bid = sum(yesterday_bids) / float(len(yesterday_bids))

    hp = float(my_status['hp'])
    budget = float(my_status['budget'])

    # Determine how aggressive to be based on yesterday's bidding intensity
    # If someone was bidding near our daily salary, expect a scramble for water.
    scramble = highest_prev_bid >= DAILY_SALARY * 0.85

    # Supply pressure: higher supply reduces marginal value of extra bids.
    # Lower supply increases need to win water.
    supply_mid = (MIN_SUPPLY + MAX_SUPPLY) / 2.0
    low_supply = supply <= supply_mid

    # Compute target bid
    if scramble:
        # Price war likely; we bid enough to compete but not max out.
        if hp <= 2.0:
            target = DAILY_SALARY * 0.9
        elif low_supply:
            target = max(avg_prev_bid, DAILY_SALARY * 0.7)
        else:
            target = max(avg_prev_bid * 0.85, DAILY_SALARY * 0.6)
    else:
        # Not a scramble; bid to secure without overspending.
        if low_supply:
            target = max(avg_prev_bid * 0.8, DAILY_SALARY * 0.55)
        else:
            target = max(avg_prev_bid * 0.65, DAILY_SALARY * 0.45)

    # Budget safety cap: never bid above budget; also avoid extreme bids.
    # Use a soft cap relative to remaining budget.
    cap = budget
    if cap <= 0:
        return 0.0

    # If we are healthy, reduce bids slightly to conserve.
    if hp >= 7.0:
        target *= 0.9
    elif hp <= 3.0:
        target *= 1.05

    # Final bid
    bid = min(cap, target)
    if bid < 0.0:
        bid = 0.0
    return float(bid)

def get_bid(day_context, my_status, opponents_status):
    DAILY_SALARY = 80
    WATER_REQ = 7
    supply = day_context['supply']
    budget = my_status['budget']
    hp = my_status['hp']

    alive_opponents = [o for o in opponents_status.values() if o['alive']]
    if not alive_opponents:
        return min(budget, 20.0)

    avg_opp_bid = 0
    bids = [o['previous_trace']['bid'] for o in alive_opponents if o.get('previous_trace') and o['previous_trace'].get('bid') is not None]
    if bids:
        avg_opp_bid = sum(bids) / len(bids)

    if hp <= 3:
        return min(budget, DAILY_SALARY * 0.95)

    if supply < 18:
        return min(budget, max(avg_opp_bid * 1.05, DAILY_SALARY * 0.7))

    return min(budget, max(40.0, avg_opp_bid * 0.8))
